// Reference solution
function findVerifyKey(header, jwks) {
  if (!header.kid) return 'NO_KID';
  for (var i = 0; i < jwks.keys.length; i++) if (jwks.keys[i].kid === header.kid) return jwks.keys[i];
  return 'UNKNOWN_KID';
}

